//! Weathered plates against the Ruby original: seeded inscriptions must be
//! byte-identical, and the editions must read the same (fixtures generated by
//! tests/fixtures/gen_weathering_fixtures.rb).

use std::collections::BTreeMap;

use rustergraphia::grille::{Grille, Part};
use rustergraphia::layout::Layout;
use rustergraphia::svg::Damage;
use rustergraphia::{cipher, lacunae, tally, Line, RubyRandom, Value};
use serde_json::Value as Json;

fn vectors() -> Json {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/weathering_vectors.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn layout_of(name: &str) -> Layout {
    match name.strip_prefix("grille:") {
        Some(key) => Layout::Grille(Grille::new(key, Part::Whole).unwrap()),
        None => Layout::keyless(name).unwrap(),
    }
}

fn values(json: &Json) -> Vec<Value> {
    json.as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_u64().unwrap() as Value)
        .collect()
}

fn damage_of(json: &Json) -> Damage {
    let mut damage = BTreeMap::new();
    for entry in json.as_array().unwrap() {
        let pair = entry.as_array().unwrap();
        let index = pair[0].as_u64().unwrap() as usize;
        let lost: Vec<Line> = pair[1]
            .as_array()
            .unwrap()
            .iter()
            .map(|line| {
                let l: Vec<i32> = line
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|n| n.as_i64().unwrap() as i32)
                    .collect();
                [l[0], l[1], l[2], l[3]]
            })
            .collect();
        damage.insert(index, lost);
    }
    damage
}

#[test]
fn seeded_weathered_plates_match_ruby_byte_for_byte() {
    for case in vectors()["cases"].as_array().unwrap() {
        let layout = layout_of(case["layout"].as_str().unwrap());
        let mut random = RubyRandom::new(case["seed"].as_i64().unwrap());
        let (sequence, svg, damage) = lacunae::inscribe(
            case["message"].as_str().unwrap(),
            &layout,
            None,
            case["tally"].as_bool().unwrap(),
            case["pathless"].as_bool().unwrap(),
            &mut random,
        )
        .unwrap();
        let name = case["layout"].as_str().unwrap();
        assert_eq!(sequence, values(&case["sequence"]), "sequence for {name}");
        assert_eq!(damage, damage_of(&case["damage"]), "damage for {name}");
        assert_eq!(svg, case["svg"].as_str().unwrap(), "svg bytes for {name}");
    }
}

#[test]
fn ruby_weathered_plates_restore_to_ruby_editions() {
    for case in vectors()["cases"].as_array().unwrap() {
        let name = case["layout"].as_str().unwrap();
        let svg = case["svg"].as_str().unwrap();
        let layout = layout_of(name);
        let given = layout.is_grille().then_some(&layout);
        assert!(lacunae::is_weathered(svg).unwrap(), "{name} is weathered");
        let edition = cipher::decode(svg, None, given).unwrap();
        assert_eq!(
            edition,
            case["edition"].as_str().unwrap(),
            "edition for {name}"
        );
        match case["survey_layout"].as_str() {
            Some(expected) => assert_eq!(
                lacunae::survey::layout(svg).unwrap(),
                Some(Layout::keyless(expected).unwrap()),
                "survey layout for {name}"
            ),
            None if !case["pathless"].as_bool().unwrap() && name.starts_with("grille") => {
                assert_eq!(lacunae::survey::layout(svg).unwrap(), None);
            }
            None => {}
        }
    }
}

#[test]
fn the_survey_shows_the_file_and_nothing_more() {
    for case in vectors()["cases"].as_array().unwrap() {
        let name = case["layout"].as_str().unwrap();
        if name.starts_with("grille") || case["pathless"].as_bool().unwrap() {
            continue;
        }
        let svg = case["svg"].as_str().unwrap();
        let layout = layout_of(name);
        let sequence = values(&case["sequence"]);
        let damage = damage_of(&case["damage"]);
        let shown = lacunae::survey::values(svg, &layout).unwrap();
        for (index, value) in sequence.iter().enumerate() {
            if damage.contains_key(&index) {
                assert_eq!(shown[index], None, "worn sign {index} on {name} is open");
            } else {
                assert_eq!(shown[index], Some(*value), "sign {index} on {name}");
            }
        }
        let damaged = lacunae::survey::damaged(svg, &layout).unwrap();
        let listed: BTreeMap<usize, Vec<Line>> = damaged
            .iter()
            .map(|sign| (sign.index, sign.lost.clone()))
            .collect();
        assert_eq!(listed, damage, "lost positions on {name}");
        for sign in &damaged {
            assert!(
                sign.candidates.contains(&sequence[sign.index]),
                "the lost value is among the candidates on {name}"
            );
        }
    }
}

#[test]
fn sampling_four_to_ten_matches_mri() {
    // Ruby 3.3: (0...len).to_a.sample(n, random: Random.new(seed))
    let cases: [(i64, usize, usize, &[usize]); 4] = [
        (4, 10, 72, &[46, 56, 71, 1, 52, 10, 63, 60, 61, 65]),
        (5, 4, 20, &[3, 15, 17, 7]),
        (6, 10, 11, &[10, 9, 3, 5, 2, 8, 4, 0, 7, 6]),
        (7, 11, 30, &[15, 5, 27, 25, 7, 24, 29, 14, 22, 17, 1]),
    ];
    for (seed, n, len, expected) in cases {
        let mut random = RubyRandom::new(seed);
        assert_eq!(random.sample_indices(n, len), expected, "seed {seed}");
    }
}

#[test]
fn tally_sums_match_ruby() {
    let v = vectors();
    let reference = &v["tally_ref"];
    for case in reference["adds"].as_array().unwrap() {
        let pair = case.as_array().unwrap();
        assert_eq!(
            tally::add(&values(&pair[0])),
            pair[1].as_u64().unwrap() as Value
        );
    }
    let sequence = values(&reference["sequence"]);
    let signs = tally::signs(&sequence, &Layout::Phaistos).unwrap();
    assert_eq!(signs.rows, values(&reference["rows"]));
    assert_eq!(signs.cols, values(&reference["cols"]));
    assert_eq!(signs.corner, reference["corner"].as_u64().unwrap() as Value);
    assert_eq!(tally::add(&signs.rows), signs.corner);
    assert_eq!(tally::add(&signs.cols), signs.corner);
}

#[test]
fn a_worn_pathless_plate_lies_in_grid_order() {
    let v = vectors();
    let case = v["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|case| case["pathless"].as_bool().unwrap())
        .unwrap();
    let svg = case["svg"].as_str().unwrap();
    assert!(rustergraphia::pathless::is_pathless(svg));
    for layer in [
        rustergraphia::svg::Layer::Strokes,
        rustergraphia::svg::Layer::Lacunae,
    ] {
        let cells: Vec<(i32, i32)> = rustergraphia::svg::lines(svg, layer)
            .unwrap()
            .into_iter()
            .map(|line| rustergraphia::layout::cell_of(line, &Layout::Phaistos))
            .collect();
        let mut deduped = cells.clone();
        deduped.dedup();
        let mut sorted = deduped.clone();
        sorted.sort();
        assert_eq!(deduped, sorted, "{layer:?} lie in grid order");
    }
    // the survey says what each worn cell may hold, read both ways up
    let worn = lacunae::survey::worn_cells(svg).unwrap();
    assert!(!worn.is_empty());
    let sequence = values(&case["sequence"]);
    let damage = damage_of(&case["damage"]);
    let path = rustergraphia::layout::path(sequence.len().isqrt(), &Layout::Leap).unwrap();
    for (row, col, upright, turned) in &worn {
        let index = path
            .iter()
            .position(|&(r, c, _)| (r, c) == (*row, *col))
            .unwrap();
        let reading = if path[index].2 { turned } else { upright };
        let reading = reading.as_ref().expect("the written way up reads");
        assert!(reading.candidates.contains(&sequence[index]));
        let mut lost = reading.lost.clone();
        lost.sort();
        let mut expected = damage[&index].clone();
        expected.sort();
        assert_eq!(lost, expected);
    }
}
